         "text": "«Я не могу предсказать будущее. Я не могу гарантировать, что всё будет легко и хорошо. Но я и не обязан это делать. Моя задача — не предсказывать, а вносить свою часть. Моя часть — это конкретные дети. Их безопасность, их доверие, их умение говорить о чувствах, мириться, просить помощь, не сдаваться после ошибки и сохранять надежду в трудные времена. Эти качества останутся с ними. Они повлияют на их будущие семьи, коллективы, города. Если таких детей будет много, Россия действительно станет страной счастливых людей. Не потому что кто-то один устранил все проблемы, а потому что многие не отказались от своей части и научились быть устойчивыми. Я могу признать трудности, не отрицая боль. Но я выбираю не передавать детям безнадёжность. Я даю им опыт человечности. Конкретно от меня зависит моя часть будущего России»."
